import json,re,subprocess
checks={
 'connection_refused':r'connection refused|ECONNREFUSED|ConnectException',
 'database':r'\bdatabase\b|\bpostgres(?:ql)?\b|\bmysql\b',
 'payment_gateway':r'payment[- _]gateway',
 'gateway':r'\bgateway\b',
 'service_unavailable':r'service unavailable|\b503\b',
 'localhost':r'\blocalhost\b|\b127\.0\.0\.1\b',
 'network':r'\bnetwork\b',
 'dns':r'\bDNS\b|UnknownHostException|name resolution',
 'timeout':r'timed?\s*out|timeout',
 'permission_denied':r'permission denied|access denied',
 'test_failure':r'test.*(?:fail|error)|(?:fail|error).*test',
 'build_step_failure':r'step.*(?:fail|error)|(?:fail|error).*step',
 'credential_marker':r'canary|token|password|secret|credential|bearer',
}
def flags(s):return [k for k,v in checks.items() if re.search(v,s,re.I)]
for mode in ('tail','failed'):
 cmd=['teamcity','run','log','482193']+(['--tail','80'] if mode=='tail' else ['--failed'])+['--json','--no-input']
 r=subprocess.run(cmd,capture_output=True,text=True)
 out={'source':'log_'+mode,'exit_code':r.returncode,'stderr_present':bool(r.stderr.strip())}
 if r.returncode==0:
  try:j=json.loads(r.stdout)
  except Exception as e:out['parse_error']=type(e).__name__;print(json.dumps(out));continue
  if isinstance(j,dict):
   out['run_id']=j.get('run_id') if isinstance(j.get('run_id'),(str,int)) else None
   messages=j.get('messages')
   if isinstance(messages,list):
    out['message_count']=len(messages)
    out['messages']=[]
    for index,msg in enumerate(messages):
     row={'index':index,'signals':flags(json.dumps(msg))}
     if isinstance(msg,dict):
      row['field_names']=list(msg)
      row['metadata']={k:v for k,v in msg.items() if k in ('id','timestamp','time','level','type','status') and isinstance(v,(int,float,bool))}
     out['messages'].append(row)
   else:out['signals']=flags(json.dumps(j))
  else:out['signals']=flags(json.dumps(j))
  out['raw_text_omitted']=True
 else:out['result']='unreadable; raw diagnostic suppressed'
 print(json.dumps(out,sort_keys=True))
PY

