        return {'exit_code':p.returncode,'response':'Non-JSON response withheld','stdout_bytes':len(p.stdout.encode()),'stderr_bytes':len(p.stderr.encode())}
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
    for r in pool.map(read,commands): print(json.dumps(r,indent=2))
